from jsonb_to_recordset($json$[{"id":"che-ek-221","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Molecularity is a meaningful idea only for","options":["an elementary step","every complex multi-step reaction as a whole","equilibrium constants","conductivity experiments"],"answer_index":0,"explanation":"A complex reaction is a sequence of elementary steps; it has an order but not a single molecularity.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"order-molecularity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-222","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Decomposition of a single gaseous molecule in one elementary act is described as","options":["unimolecular","bimolecular","zero-order by definition","termolecular only"],"answer_index":0,"explanation":"One reactant species appears in the elementary step, so the molecularity is one.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"order-molecularity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-223","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A bimolecular elementary reaction involves","options":["a collision between two species (like or unlike)","the simultaneous meeting of four molecules","no collision at all","only a change of solvent polarity"],"answer_index":0,"explanation":"Two particles must encounter each other; the step is first order in each (or second order in one if they are identical).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"order-molecularity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-224","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Ammonia decomposition on a tungsten surface at high pressure is a familiar textbook example of a","options":["zero-order reaction","third-order gas reaction","unimolecular reaction in the gas phase only","reaction with no rate constant"],"answer_index":0,"explanation":"The surface is saturated, so the rate becomes independent of the NH$_3$ pressure: order zero.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"order-molecularity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-225","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The experimental law rate $= k[\\mathrm{H_2}][\\mathrm{Br_2}]^{1/2}$ has overall order","options":["1.5","2","0.5","1"],"answer_index":0,"explanation":"Exponents add: $1 + 1/2 = 3/2$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"order-molecularity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-226","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Acid-catalysed hydrolysis of methyl acetate in a large excess of water is treated as","options":["pseudo first order in the ester","second order in water","zero order in the ester","third order overall under all conditions"],"answer_index":0,"explanation":"[H$_2$O] is essentially constant, so the observed rate is first order in ester only.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"order-molecularity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-227","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For a reaction that proceeds by several elementary steps, the overall order","options":["need not equal the molecularity of any one step, and is found only by experiment","is always equal to the number of steps","must equal the molecularity of the last step","is undefined if a catalyst is present"],"answer_index":0,"explanation":"Order is a property of the observed rate law. Molecularity belongs to individual steps.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"order-molecularity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-228","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Termolecular elementary steps are rare because","options":["a simultaneous collision of three molecules is statistically improbable","three molecules can never share electrons","the collision theory forbids $n = 3$ exactly","Faraday's laws prohibit them"],"answer_index":0,"explanation":"Two-body collisions are common; a third body arriving in the same instant is unlikely, so $n = 3$ steps are scarce.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"order-molecularity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-229","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A rate constant reported as L$^2$ mol$^{-2}$ s$^{-1}$ indicates that the reaction is","options":["third order overall","first order overall","zero order overall","fractional order of ½"],"answer_index":0,"explanation":"Units of $k$ are (conc.)$^{1-n}$ (time)$^{-1}$. L$^2$ mol$^{-2}$ s$^{-1}$ corresponds to $n = 3$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"order-molecularity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-230","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Mechanism: fast equilibrium A + B ⇌ I, followed by slow I → P. The observed order in A and the molecularity of the slow step are","options":["first order in A, and unimolecular","second order in A, and bimolecular","zero order in A, and termolecular","first order in A, and bimolecular"],"answer_index":0,"explanation":"The RDS is unimolecular in I. Substituting [I] = $K[\\mathrm{A}][\\mathrm{B}]$ makes the rate first order in A (and in B).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"order-molecularity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-231","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The integrated first-order rate law is commonly written","options":["$\\ln([\\mathrm{A}]_0/[\\mathrm{A}]) = kt$","$[\\mathrm{A}] = [\\mathrm{A}]_0 - kt$","$1/[\\mathrm{A}] - 1/[\\mathrm{A}]_0 = kt$","$[\\mathrm{A}]^2 = kt$"],"answer_index":0,"explanation":"Integration of $-\\mathrm{d}[\\mathrm{A}]/\\mathrm{d}t = k[\\mathrm{A}]$ yields a linear plot of $\\ln[\\mathrm{A}]$ versus $t$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-232","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For a zero-order decay the concentration falls linearly according to","options":["$[\\mathrm{A}] = [\\mathrm{A}]_0 - kt$","$\\ln[\\mathrm{A}] = \\ln[\\mathrm{A}]_0 - kt$","$1/[\\mathrm{A}] = 1/[\\mathrm{A}]_0 + kt$","$[\\mathrm{A}] = [\\mathrm{A}]_0 e^{+kt}$"],"answer_index":0,"explanation":"Rate $= k$ (constant), so [A] drops at a constant slope $-k$ until the reactant is exhausted.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
    id text,
